:host {
    display: block;
    min-width: 0;
    --rr-line: #e5e5e5;
    --rr-muted: #5c5c5c;
    --rr-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

.rr-dv { border: 1px solid var(--rr-line); border-radius: 4px; overflow: hidden; min-width: 0; background: #fff; color: #181818; }
.rr-dvh { display: flex; align-items: center; gap: 10px; padding: 8px 10px; background: #fafaf9; border-bottom: 1px solid var(--rr-line); font-size: 13px; min-width: 0; }
.rr-path { font-family: var(--rr-mono); font-size: 12.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.rr-cnt { display: inline-flex; gap: 4px; font-size: 12px; white-space: nowrap; }
.rr-plus { color: #2e844a; font-weight: 700; }
.rr-minus { color: #ba0517; font-weight: 700; }
.rr-grow { flex: 1; min-width: 0; }
.rr-link { color: #0b5cab; text-decoration: none; white-space: nowrap; font-size: 12px; }
.rr-link:hover, .rr-link:focus { text-decoration: underline; }
.rr-small { font-size: 12px; }
.rr-weak { color: var(--rr-muted); }

/* Split / Unified */
.rr-seg { display: inline-flex; border: 1px solid #c9c9c9; border-radius: 4px; overflow: hidden; flex: none; }
.rr-seg-btn { padding: 3px 10px; font: inherit; font-size: 12px; color: #0b5cab; background: #fff; border: 0; cursor: pointer; }
.rr-seg-btn + .rr-seg-btn { border-left: 1px solid #c9c9c9; }
.rr-seg-on { background: #0176d3; color: #fff; font-weight: 700; }

.rr-pill { display: inline-flex; align-items: center; height: 20px; padding: 0 8px; border-radius: 10px; font-size: 11px; font-weight: 700; white-space: nowrap; flex: none; }
.rr-pill-ok { background: #ebf7e6; color: #2e844a; }
.rr-pill-bad { background: #feded8; color: #8e030f; }
.rr-pill-none { background: #f3f3f3; color: #444; }
.rr-pill-src { background: #e1f5ee; color: #0f6e56; }

/* states */
.rr-empty { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; padding: 20px 16px; font-size: 13px; }
.rr-empty p { margin: 0; line-height: 1.45; }
.rr-nf { display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-bottom: 1px solid var(--rr-line); }

/* side by side: each side scrolls sideways on its own; the page never does */
.rr-sbs { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.rr-sbh { display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-bottom: 1px solid var(--rr-line); font-size: 12.5px; min-width: 0; }
.rr-sbh + .rr-sbh, .rr-scr + .rr-scr { border-left: 1px solid var(--rr-line); }
.rr-scr { overflow-x: auto; min-width: 0; }

.rr-df { border-collapse: collapse; width: 100%; font-family: var(--rr-mono); font-size: 12px; line-height: 20px; }
.rr-df td { padding: 0; white-space: pre; vertical-align: top; height: 20px; }
.rr-n { width: 34px; min-width: 34px; text-align: right; color: #939393; user-select: none; background: #fafaf9; }
.rr-df td.rr-n { padding-right: 6px; }
.rr-g { width: 14px; min-width: 14px; text-align: center; color: #939393; user-select: none; }
.rr-df td.rr-c { padding-right: 12px; }

.rr-del td { background: #fef1ee; }
.rr-del .rr-n { background: #fdddd7; color: #8e030f; }
.rr-del .rr-g { color: #ba0517; }
.rr-del .rr-mk { background: #f9b7ac; }
.rr-add td { background: #ebf7e6; }
.rr-add .rr-n { background: #d5efcb; color: #22683e; }
.rr-add .rr-g { color: #2e844a; }
.rr-add .rr-mk { background: #a6e3a0; }
.rr-mk { color: inherit; border-radius: 2px; }
.rr-pad td { background: repeating-linear-gradient(135deg, #fafaf9 0 6px, #f3f3f3 6px 7px); }

.rr-fold td { background: #f3f6fa; height: 26px; border-top: 1px solid #e5eaf2; border-bottom: 1px solid #e5eaf2; }
.rr-fold-btn {
    display: block; width: 100%; height: 26px; padding: 0 12px; border: 0; background: transparent; text-align: left;
    color: #0b5cab; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; font-size: 12px; line-height: 26px; cursor: pointer;
}
span.rr-fold-btn { cursor: default; }
button.rr-fold-btn:hover, button.rr-fold-btn:focus { text-decoration: underline; }
.rr-hunk td { background: #f3f6fa; color: var(--rr-muted); height: 24px; line-height: 24px; }
.rr-df td.rr-hunk-text { padding-left: 8px; }
